import csv
import io
import re
from collections import Counter


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    def read_with_delimiter(delimiter):
        comments = []

        def lines():
            in_quotes = False
            field_start = True
            for line in io.StringIO(raw_csv, newline=""):
                if not in_quotes and line.lstrip().startswith("#"):
                    comments.append(line.lstrip()[1:].strip())
                    continue

                i = 0
                while i < len(line):
                    char = line[i]
                    if in_quotes:
                        if char == '"':
                            if i + 1 < len(line) and line[i + 1] == '"':
                                i += 1
                            else:
                                in_quotes = False
                    elif char == '"' and field_start:
                        in_quotes = True
                        field_start = False
                    elif char == delimiter:
                        field_start = True
                    elif char in "\r\n":
                        field_start = True
                    else:
                        field_start = False
                    i += 1
                yield line

        rows = [row for row in csv.reader(lines(), delimiter=delimiter) if row]
        return rows, comments

    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))

        candidates = []
        for delimiter in ("\t", ";", ",", "|"):
            rows, comments = read_with_delimiter(delimiter)
            widths = Counter(len(row) for row in rows if len(row) > 1)
            if widths:
                width, count = max(widths.items(), key=lambda item: (item[1], item[0]))
                score = (count, count / max(len(rows), 1), width)
            else:
                score = (0, 0, 1)
            candidates.append((score, delimiter, rows, comments))

        _, delimiter, rows, comments = max(candidates, key=lambda item: item[0])
    finally:
        csv.field_size_limit(old_limit)

    if not rows:
        return {"columns": [], "rows": []}

    width_counts = Counter(len(row) for row in rows)
    typical_width = max(width_counts, key=lambda width: (width_counts[width], width))

    def valid_names(text):
        parts = [part.strip() for part in text.split(delimiter)]
        if len(parts) < 2:
            return None
        if all(re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ -]*", part) for part in parts):
            return parts
        return None

    described_header = None
    for comment in comments:
        possibilities = re.findall(r"\(([^()]*)\)", comment)
        possibilities.append(comment)
        for possibility in possibilities:
            names = valid_names(possibility)
            if names and len(names) == typical_width:
                described_header = names
                break
        if described_header:
            break

    def same_names(left, right):
        return len(left) == len(right) and all(
            a.strip().casefold() == b.strip().casefold()
            for a, b in zip(left, right)
        )

    def looks_like_header(row):
        return len(row) > 1 and all(
            re.fullmatch(r"[A-Za-z_][A-Za-z0-9_ -]*", value.strip())
            for value in row
        )

    if described_header and same_names(rows[0], described_header):
        columns = rows.pop(0)
    elif described_header and not looks_like_header(rows[0]):
        columns = described_header
    else:
        columns = rows.pop(0)

    max_width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    for index in range(len(columns), max_width):
        name = "column_" + str(index + 1)
        while name in used:
            name += "_"
        columns.append(name)
        used.add(name)

    normalized = [row + [""] * (max_width - len(row)) for row in rows]
    return {"columns": columns, "rows": normalized}
